return {api_version=1,id="NEW1_030",name="Deathwing",text="<b>Battlecry:</b> Destroy all other minions and discard your hand.",set="EXPERT1",type="minion",rarity="legendary",cost=10,attack=12,health=12,tags={"dragon"},keywords={"battlecry"},on_battlecry=function(ctx,self)local r={};for _,e in ipairs(ctx:minions())do if e~=self then r[#r+1]=e end end;ctx:destroy_all(r);local p=ctx:controller(self);for _,e in ipairs(ctx:hand(p))do ctx:discard(p,e)end end}
